PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://brickschema.org/schema/1.2/bricks-ext#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?ts ?point ?label ?pc WHERE {
  ?point a brick:Occupancy .
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point rdfs:label ?label }
  ?point brick:hasProperty ?pc .
} LIMIT 50

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://brickschema.org/schema/1.2/bricks-ext#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?zlabel WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?zlabel }
} LIMIT 60

